function MatrixRain(){
 const ref=useRef<HTMLCanvasElement|null>(null)
 useEffect(()=>{
  const canvas=ref.current; if(!canvas)return
  const ctx=canvas.getContext('2d'); if(!ctx)return
  let raf=0, drops:number[]=[]
  const chars='01ROGUEAI<>/{}[]$#@%+=*ABCDEFGHIJKLMNOPQRSTUVWXYZ'
  const resize=()=>{const d=Math.min(window.devicePixelRatio||1,2); canvas.width=Math.floor(innerWidth*d); canvas.height=Math.floor(innerHeight*d); canvas.style.width=innerWidth+'px'; canvas.style.height=innerHeight+'px'; ctx.setTransform(d,0,0,d,0,0); const cols=Math.ceil(innerWidth/17); drops=Array.from({length:cols},()=>Math.random()*-80)}
  const draw=()=>{ctx.fillStyle='rgba(2,6,4,.13)';ctx.fillRect(0,0,innerWidth,innerHeight);ctx.font='12px ui-monospace,monospace';for(let i=0;i<drops.length;i++){const x=i*17,y=drops[i]*17;ctx.fillStyle=i%13===0?'rgba(170,255,150,.9)':'rgba(50,255,100,.34)';ctx.fillText(chars[(Math.random()*chars.length)|0],x,y);if(y>innerHeight&&Math.random()>.975)drops[i]=Math.random()*-20;drops[i]+=.55}raf=requestAnimationFrame(draw)}
  resize(); addEventListener('resize',resize); draw(); return()=>{cancelAnimationFrame(raf);removeEventListener('resize',resize)}
 },[])
 return <canvas ref={ref} className="matrixRain" aria-hidden="true"/>
}

