function TokenLogo({src,symbol,name}:{src?:string|null;symbol?:string;name?:string}){const [bad,setBad]=useState(false);const initials=(symbol||name||'?').slice(0,3).toUpperCase();if(!src||bad)return <span className="token tokenFallback">{initials}</span>;return <span className="token tokenImage"><img src={src} alt="" loading="lazy" onError={()=>setBad(true)}/></span>}
function LiveChart({query}:{query:string}){
 const [tf,setTf]=useState('5m'),[candles,setCandles]=useState<Candle[]>([]),[status,setStatus]=useState('LOADING'),[error,setError]=useState(''),[updated,setUpdated]=useState('')
 const load=async()=>{
  if(!query.trim()){setStatus('WAITING');return}
  try{
   const r=await fetch(`/api/chart?q=${encodeURIComponent(query.trim())}&tf=${encodeURIComponent(tf)}&limit=180`,{cache:'no-store'})
   const d=await r.json()
   if(!r.ok||!d?.ok){setCandles([]);setError(d?.error||'No verified candles returned.');setStatus('UNAVAILABLE');return}
   setCandles(Array.isArray(d.candles)?d.candles:[]);setError('');setUpdated(d.observedAt||new Date().toISOString());setStatus('LIVE')
  }catch{setCandles([]);setError('Live chart provider request failed safely.');setStatus('UNAVAILABLE')}
 }
 useEffect(()=>{load();const id=window.setInterval(load,20000);return()=>window.clearInterval(id)},[query,tf])
 const width=900,height=300,pad=28
 const min=candles.length?Math.min(...candles.map(c=>c.low)):0,max=candles.length?Math.max(...candles.map(c=>c.high)):1
 const range=max-min||1
 const x=(i:number)=>pad+(i/Math.max(1,candles.length-1))*(width-pad*2)
 const y=(v:number)=>height-pad-((v-min)/range)*(height-pad*2)
 const bodyW=Math.max(2,Math.min(9,(width-pad*2)/Math.max(1,candles.length)*.65))
 const latest=candles[candles.length-1]
 const first=candles[0]
 const line=candles.map((c,i)=>`${x(i)},${y(c.close)}`).join(' ')
 return <div className="liveChartShell">
  <div className="liveChartTop"><div><b>LIVE CANDLES</b><span>{status} · GECKOTERMINAL · {candles.length?`${candles.length} BARS`:error||'WAITING'}</span></div><div className="chartTf">{['1m','5m','15m','1h','4h','12h','1d'].map(x=><button key={x} className={tf===x?'active':''} onClick={()=>setTf(x)}>{x}</button>)}</div></div>
  {candles.length?<div className="liveChartViewport"><svg viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none" role="img" aria-label="Live token candlestick chart"><g className="chartGridLines"><line x1={pad} x2={width-pad} y1={y(min)} y2={y(min)}/><line x1={pad} x2={width-pad} y1={y((min+max)/2)} y2={y((min+max)/2)}/><line x1={pad} x2={width-pad} y1={y(max)} y2={y(max)}/></g><polyline className="chartCloseLine" points={line}/>{candles.map((c,i)=>{const up=c.close>=c.open;const top=y(Math.max(c.open,c.close)),bottom=y(Math.min(c.open,c.close));return <g key={`${c.time}-${i}`} className={up?'candleUp':'candleDown'}><line x1={x(i)} x2={x(i)} y1={y(c.high)} y2={y(c.low)}/><rect x={x(i)-bodyW/2} y={Math.min(top,bottom)} width={bodyW} height={Math.max(1,Math.abs(bottom-top))}/></g>})}</svg><div className="chartPriceAxis"><span>{max.toLocaleString(undefined,{maximumFractionDigits:max<1?8:4})}</span><span>{((max+min)/2).toLocaleString(undefined,{maximumFractionDigits:max<1?8:4})}</span><span>{min.toLocaleString(undefined,{maximumFractionDigits:min<1?8:4})}</span></div></div>:<div className="liveChartEmpty"><b>{status==='LOADING'?'CONNECTING TO LIVE CANDLES': 'NO VERIFIED CANDLES'}</b><span>{error||'ROGUE will not draw synthetic price history.'}</span><button onClick={load}>RETRY LIVE CHART</button></div>}
  <div className="liveChartFoot"><span>{latest?`LAST $${latest.close.toLocaleString(undefined,{maximumFractionDigits:latest.close<1?10:6})}`:'—'}</span><span>{first&&latest?`${((latest.close-first.open)/first.open*100).toFixed(2)}% over loaded window`:'Provider history unavailable'}</span><span>{updated?`UPDATED ${new Date(updated).toLocaleTimeString()}`:'—'}</span></div>
 </div>
}

